import unittest
import cli


class New(unittest.TestCase):
    def test_csv_header(self):
        self.assertEqual(cli.render('csv').splitlines()[0], 'name,qty')
    def test_csv_rows(self):
        self.assertEqual(cli.render('csv').splitlines()[1:], ['a,1', 'b,2'])
    def test_main_csv(self):
        cli.main(['--format', 'csv'])
